mapper.select:
SELECT 
FROM sys_notification
WHERE user_id = #{userId}
AND type = #{type}
ORDER BY created_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM sys_notification
WHERE user_id = #{userId}
AND type = #{type}

mapper.update:
UPDATE sys_notification
SET is_read = 1
WHERE id = #{id} AND user_id = #{userId}

mapper.delete:
DELETE FROM sys_notification
WHERE user_id = #{userId}
  AND type = #{type}
  AND DATE(created_at) = CURDATE()
